package com.kartikey.ares;
import android.app.Activity;import android.os.Bundle;import android.os.VibrationEffect;import android.os.Vibrator;import android.os.Build;import android.webkit.JavascriptInterface;import android.webkit.WebSettings;import android.webkit.WebView;import android.webkit.WebViewClient;import android.view.Window;
public class MainActivity extends Activity{private WebView web;@Override public void onCreate(Bundle b){super.onCreate(b);Window w=getWindow();w.setStatusBarColor(android.graphics.Color.rgb(8,9,11));w.setNavigationBarColor(android.graphics.Color.rgb(8,9,11));web=new WebView(this);setContentView(web);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setDatabaseEnabled(true);s.setAllowFileAccess(true);s.setAllowContentAccess(true);web.setBackgroundColor(android.graphics.Color.rgb(8,9,11));web.setWebViewClient(new WebViewClient());web.addJavascriptInterface(new Haptics(),"AresNative");web.loadUrl("file:///android_asset/index.html");}@Override public void onBackPressed(){if(web.canGoBack())web.goBack();else super.onBackPressed();}public class Haptics{@JavascriptInterface public void haptic(){Vibrator v=(Vibrator)getSystemService(VIBRATOR_SERVICE);if(v==null||!v.hasVibrator())return;if(Build.VERSION.SDK_INT>=26)v.vibrate(VibrationEffect.createOneShot(60,VibrationEffect.DEFAULT_AMPLITUDE));else v.vibrate(60);}}}
